    /*
     * Add to the Reserves
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Exposure
     */
    public Exposure addToReserves( UUID parentId, ClaimReserve addTo ) {
	    LOGGER.info("handling AssignReservesToExposureEvent - " );
	    
	    Exposure parentEntity = repository.findById(parentId).get();
	    ClaimReserve child = registry.project( ClaimReserve.class, addTo.getClaimReserveId());
	    
	    parentEntity.getReserves().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Reserves
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Exposure
     */
	public Exposure removeFromReserves( UUID parentId, ClaimReserve removeFrom ) {
	    LOGGER.info("handling RemoveReservesFromExposureEvent " );
	
	    Exposure parentEntity = repository.findById(parentId).get();
	    ClaimReserve child = registry.project( ClaimReserve.class, removeFrom.getClaimReserveId());
	    
	    parentEntity.getReserves().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

